using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class TripoCobaltFullSourcePrepare {
 const string PathModel="Assets/LighFight/Art/Drafts/TripoCobaltPlayable/Source/CobaltFull/model.fbx";
 public static void Prepare(){
  Directory.CreateDirectory("CobaltEvidence");var importer=(ModelImporter)AssetImporter.GetAtPath(PathModel);
  importer.useFileScale=true;importer.globalScale=1;importer.importNormals=ModelImporterNormals.Import;importer.importTangents=ModelImporterTangents.CalculateMikk;importer.indexFormat=ModelImporterIndexFormat.Auto;importer.animationType=ModelImporterAnimationType.Generic;importer.skinWeights=ModelImporterSkinWeights.Custom;importer.maxBonesPerVertex=8;importer.minBoneWeight=0;importer.meshCompression=ModelImporterMeshCompression.Off;importer.weldVertices=false;importer.isReadable=true;importer.optimizeGameObjects=false;importer.animationCompression=ModelImporterAnimationCompression.Off;importer.SaveAndReimport();
  var model=AssetDatabase.LoadAssetAtPath<GameObject>(PathModel);var skin=model.GetComponentInChildren<SkinnedMeshRenderer>();string before=MeshHash(skin.sharedMesh);
  var rest=skin.bones.ToDictionary(b=>b.name,b=>(b.localPosition,b.localRotation,b.localScale));
  TripoCobaltAvatarSetup.Configure("CobaltFull");model=AssetDatabase.LoadAssetAtPath<GameObject>(PathModel);skin=model.GetComponentInChildren<SkinnedMeshRenderer>();var avatar=AssetDatabase.LoadAllAssetsAtPath(PathModel).OfType<Avatar>().Single();
  string after=MeshHash(skin.sharedMesh);float position=skin.bones.Max(b=>Vector3.Distance(rest[b.name].Item1,b.localPosition));float rotation=skin.bones.Max(b=>Quaternion.Angle(rest[b.name].Item2,b.localRotation));float scale=skin.bones.Max(b=>Vector3.Distance(rest[b.name].Item3,b.localScale));
