  string prefix="Assets/LighFight/Art/Drafts/TripoCobaltPlayable/Source/CobaltFull/cobalt-h31-unity-native-full-pack_";
  foreach(string suffix in new[]{"basecolor","normal","metallic","roughness"}){var ti=(TextureImporter)AssetImporter.GetAtPath(prefix+suffix+".JPEG");ti.textureShape=TextureImporterShape.Texture2D;ti.textureType=suffix=="normal"?TextureImporterType.NormalMap:TextureImporterType.Default;ti.isReadable=true;ti.maxTextureSize=8192;ti.textureCompression=TextureImporterCompression.Uncompressed;ti.sRGBTexture=suffix=="basecolor";if(suffix=="normal")ti.textureType=TextureImporterType.NormalMap;ti.SaveAndReimport();}
  var metal=AssetDatabase.LoadAssetAtPath<Texture2D>(prefix+"metallic.JPEG");var rough=AssetDatabase.LoadAssetAtPath<Texture2D>(prefix+"roughness.JPEG");var px=metal.GetPixels32();var rp=rough.GetPixels32();if(px.Length!=rp.Length)throw new Exception("PBR maps differ in dimensions");for(int n=0;n<px.Length;n++)px[n]=new Color32(px[n].r,0,0,(byte)(255-rp[n].r));var pack=new Texture2D(metal.width,metal.height,TextureFormat.RGBA32,false,true);pack.SetPixels32(px);pack.Apply();File.WriteAllBytes("Assets/LighFight/Art/Drafts/TripoCobaltPlayable/Source/CobaltFull/derived-metal-smooth.png",pack.EncodeToPNG());UnityEngine.Object.DestroyImmediate(pack);AssetDatabase.Refresh();var pi=(TextureImporter)AssetImporter.GetAtPath("Assets/LighFight/Art/Drafts/TripoCobaltPlayable/Source/CobaltFull/derived-metal-smooth.png");pi.textureShape=TextureImporterShape.Texture2D;pi.sRGBTexture=false;pi.maxTextureSize=8192;pi.textureCompression=TextureImporterCompression.Uncompressed;pi.SaveAndReimport();
