 public static string MeshHash(Mesh mesh){using(var stream=new MemoryStream())using(var w=new BinaryWriter(stream)){
  w.Write(mesh.vertexCount);w.Write((int)mesh.indexFormat);var attrs=mesh.GetVertexAttributes();w.Write(attrs.Length);foreach(var a in attrs){w.Write((int)a.attribute);w.Write((int)a.format);w.Write(a.dimension);w.Write(a.stream);}
  foreach(var n in mesh.normals){w.Write(n.x);w.Write(n.y);w.Write(n.z);}foreach(var t in mesh.tangents){w.Write(t.x);w.Write(t.y);w.Write(t.z);w.Write(t.w);}foreach(var c in mesh.colors32){w.Write(c.r);w.Write(c.g);w.Write(c.b);w.Write(c.a);}
  for(int channel=0;channel<8;channel++){var uvs=new List<Vector4>();mesh.GetUVs(channel,uvs);w.Write(uvs.Count);foreach(var uv in uvs){w.Write(uv.x);w.Write(uv.y);w.Write(uv.z);w.Write(uv.w);}}
  w.Write(mesh.subMeshCount);for(int i=0;i<mesh.subMeshCount;i++){var sm=mesh.GetSubMesh(i);w.Write((int)mesh.GetTopology(i));w.Write(sm.baseVertex);w.Write(sm.firstVertex);w.Write(sm.vertexCount);var indices=mesh.GetIndices(i,false);w.Write(indices.Length);foreach(var index in indices)w.Write(index);}
  w.Write(mesh.blendShapeCount);for(int i=0;i<mesh.blendShapeCount;i++){w.Write(mesh.GetBlendShapeName(i));int frames=mesh.GetBlendShapeFrameCount(i);w.Write(frames);for(int j=0;j<frames;j++){w.Write(mesh.GetBlendShapeFrameWeight(i,j));var dv=new Vector3[mesh.vertexCount];var dn=new Vector3[mesh.vertexCount];var dt=new Vector3[mesh.vertexCount];mesh.GetBlendShapeFrameVertices(i,j,dv,dn,dt);foreach(var array in new[]{dv,dn,dt})foreach(var v in array){w.Write(v.x);w.Write(v.y);w.Write(v.z);}}}
  foreach(var v in mesh.vertices){w.Write(v.x);w.Write(v.y);w.Write(v.z);}foreach(var uv in mesh.uv){w.Write(uv.x);w.Write(uv.y);}foreach(var t in mesh.triangles)w.Write(t);foreach(var b in mesh.bindposes)for(int r=0;r<4;r++)for(int c=0;c<4;c++)w.Write(b[r,c]);
  using(var counts=mesh.GetBonesPerVertex())using(var weights=mesh.GetAllBoneWeights()){foreach(var n in counts)w.Write(n);foreach(var b in weights){w.Write(b.boneIndex);w.Write(b.weight);}}
  using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(stream.ToArray())).Replace("-","").ToLowerInvariant();
 }}
